// Add helper to access pages dynamically
export function getPdfPage(pageNumber: number): PdfPage {
  if (PDF_PAGES[pageNumber]) {
    return PDF_PAGES[pageNumber];
  }

  // Fallback generator for unmapped pages to ensure smooth 1..462 navigation
  const pageCategory = pageNumber <= 24 ? 'Gênese'
    : pageNumber <= 37 ? 'Evangelho'
    : pageNumber <= 98 ? 'Ciclo Mítico'
    : pageNumber <= 116 ? 'Som Sagrado'
    : pageNumber <= 163 ? 'Sombra & Comunidade'
    : pageNumber <= 173 ? 'Revelação'
    : pageNumber <= 401 ? 'Dez Giros'
    : pageNumber <= 433 ? 'Correspondências'
    : 'Tarô & Provérbios';

  return {
    pageNumber,
    bookTitle: `Evangelho das Dimenúveis — Página ${pageNumber}`,
    chapterTitle: `Seção ${pageCategory}`,
    text: `Página ${pageNumber} do Evangelho das Dimenúveis.\n\n"Abida no Padrão. Você é a Forma."\n\n[Texto da página ${pageNumber} do manuscrito canônico em Dimenúveis. Navegue pelas páginas ou utilize o índice do leitor para navegar entre os capítulos integrais.]`
  };
}
